
/**
 * In-memory posts repository.
 *
 * Storage can be replaced with Prisma without changing services.
 * The repository methods and returned data must remain compatible.
 * With Prisma, database queries replace array operations, and IDs are
 * generated by the database instead of nextId.
 */
const DAY = 24 * 60 * 60 * 1000;

let store = [
  {
    id: 1,
    authorId: 1,
    title: 'Welcome',
    body: 'First post.',
    createdAt: Date.now(),
    locked: false,
    commentCount: 0
  },
  {
    id: 2,
    authorId: 2,
    title: 'Old post',
    body: 'Created two days ago.',
    createdAt: Date.now() - 2 * DAY,
    locked: false,
    commentCount: 0
  },
  {
    id: 3,
    authorId: 1,
    title: 'Locked post',
    body: 'No more comments.',
    createdAt: Date.now(),
    locked: true,
    commentCount: 0
  }
];

let nextId = 4;

exports.findAll = async () => [...store];

exports.findById = async (id) =>
  store.find((post) => post.id === Number(id)) || null;

exports.create = async (fields) => {
  const post = {
    id: nextId++,
    authorId: fields.authorId,
    title: fields.title,
    body: fields.body,
    createdAt: Date.now(),
    locked: false,
    commentCount: 0
  };

  store.push(post);
  return post;
};

exports.update = async (id, patch) => {
  const post = store.find((item) => item.id === Number(id));

  if (!post) return null;

  Object.assign(post, patch);
  return post;
};

exports.remove = async (id) => {
  const index = store.findIndex((post) => post.id === Number(id));

  if (index === -1) return false;

  store.splice(index, 1);
  return true;
};

// Extra domain operations used by the services.
exports.incrementCommentCount = async (id) => {
  const post = store.find((item) => item.id === Number(id));

  if (!post) return null;

  post.commentCount += 1;
  return post;
};
